#!/usr/bin/env python3
# -*- coding: utf-8 -*-
import os
import sys
import time
import shutil
import base64
import platform
import zipfile
import urllib.request
import subprocess
import py_compile
import json
import tarfile
JARVIS_B64 = ""
UI_B64     = ""
APP_DIR_NAME = "jarvis-app"
PIP_PACKAGES_COMMON = [
    "vosk",
    "openai",
    "sounddevice",
    "numpy",
    "customtkinter",
    "httpx",
]
PIP_PACKAGES_WINDOWS = ["pygetwindow", "pyautogui", "pycaw", "pybrightness"]
PIPER_WIN_URL = (
    "https://github.com/rhasspy/piper/releases/download/"
    "2023.11.14-2/piper_windows_amd64.zip"
)
PIPER_LINUX_URL = (
    "https://github.com/rhasspy/piper/releases/download/"
    "2023.11.14-2/piper_linux_x86_64.tar.gz"
)
VOSK_URL = "https://alphacephei.com/vosk/models/vosk-model-small-ru-0.22.zip"
VOSK_ZIP_INNER = "vosk-model-small-ru-0.22"
PIPER_VOICE_BASE = (
    "https://huggingface.co/rhasspy/piper-voices/resolve/main/"
    "ru/ru_RU/dmitri/medium/ru_RU-dmitri-medium.onnx"
)
PIPER_VOICE_ONNX = PIPER_VOICE_BASE
PIPER_VOICE_JSON = (
    "https://huggingface.co/rhasspy/piper-voices/resolve/"
    "664c651454f055ed34bd83f09e024ffbc0da09ac/"
    "ru/ru_RU/dmitri/medium/ru_RU-dmitri-medium.onnx.json"
)
PIPER_VOICE_ONNX_NAME = "ru_RU-dmitri-medium.onnx"
PIPER_VOICE_JSON_NAME = "ru_RU-dmitri-medium.onnx.json"
IS_WIN = platform.system() == "Windows"
if IS_WIN:
    try:
        import ctypes
        k = ctypes.windll.kernel32
        k.SetConsoleMode(k.GetStdHandle(-11), 7)
        ENABLE_ANSI = True
    except Exception:
        ENABLE_ANSI = False
else:
    ENABLE_ANSI = True
C_RESET  = "\033[0m"  if ENABLE_ANSI else ""
C_BOLD   = "\033[1m"  if ENABLE_ANSI else ""
C_DIM    = "\033[2m"  if ENABLE_ANSI else ""
C_GREEN  = "\033[32m" if ENABLE_ANSI else ""
C_RED    = "\033[31m" if ENABLE_ANSI else ""
C_YELLOW = "\033[33m" if ENABLE_ANSI else ""
C_CYAN   = "\033[36m" if ENABLE_ANSI else ""
CLEAR       = "\033[2J\033[H" if ENABLE_ANSI else ""
HIDE_CURSOR = "\033[?25l"    if ENABLE_ANSI else ""
SHOW_CURSOR = "\033[?25h"    if ENABLE_ANSI else ""
LOG_LINES_KEPT = 8
STAGES = [
    "Создание файлов jarvis.pyc, ui.pyc",
    "Создание виртуального окружения",
    "Установка зависимостей (pip)",
    "Установка системных пакетов",
    "Загрузка голосовых моделей",
    "Установка Piper",
]
TOTAL_STAGES = len(STAGES)
state = {
    "stage_status": [" "] * TOTAL_STAGES,
    "stage_pct":    [0]   * TOTAL_STAGES,
    "log": [],
}
stage_index = {name: i for i, name in enumerate(STAGES)}
def _term_width(default=58):
    try:
        return shutil.get_terminal_size(fallback=(default, 24)).columns
    except Exception:
        return default
def _progress_bar(pct, width=16):
    pct = max(0, min(100, int(pct)))
    filled = int(width * pct / 100)
    bar = "=" * filled
    if filled < width:
        bar += ">"
        bar += " " * (width - filled - 1)
    return f"[{bar}] {pct:3d}%"
def render():
    sys.stdout.write(CLEAR)
    sys.stdout.write(HIDE_CURSOR)
    overall = sum(state["stage_pct"]) / TOTAL_STAGES if TOTAL_STAGES else 0
    w = _term_width()
    sep = "=" * min(w, 58)
    out = [sep,
           "           УСТАНОВКА J.A.R.V.I.S.".center(len(sep)),
           f"  Платформа: {get_os_label()}    {_progress_bar(overall)}",
           sep]
    for i, name in enumerate(STAGES):
        status = state["stage_status"][i]
        pct = state["stage_pct"][i]
        if status == "x":
            out.append(f"  {C_GREEN}[✓]{C_RESET} {name} {C_GREEN}{pct}%{C_RESET}")
        elif status == ">":
            out.append(f"  {C_CYAN}[>]{C_RESET} {name} {C_CYAN}{pct}%{C_RESET}")
        elif status == "!":
            out.append(f"  {C_RED}[!]{C_RESET} {name} {C_RED}{pct}%{C_RESET}")
        else:
            out.append(f"  [ ] {name}")
    out.append(sep)
    log = state["log"][-LOG_LINES_KEPT:]
    out.extend(log)
    for _ in range(LOG_LINES_KEPT - len(log)):
        out.append("")
    out.append(sep)
    sys.stdout.write("\n".join(out) + "\n")
    sys.stdout.flush()
def set_stage(name, pct=None, status=">"):
    idx = stage_index[name]
    state["stage_status"][idx] = status
    if pct is not None:
        state["stage_pct"][idx] = max(0, min(100, int(pct)))
    render()
def stage_done(name):
    idx = stage_index[name]
    state["stage_status"][idx] = "x"
    state["stage_pct"][idx] = 100
    render()
def stage_fail(name):
    state["stage_status"][stage_index[name]] = "!"
    render()
def log_line(msg):
    state["log"].append(msg)
    render()
def ok_line(msg):
    log_line(f"  {msg} {C_GREEN}[ОК]{C_RESET}")
def err_line(msg):
    log_line(f"  {msg} {C_RED}[ОШИБКА]{C_RESET}")
def info_line(msg):
    log_line(f"  {C_DIM}{msg}{C_RESET}")
def detect_os():
    if IS_WIN:
        return "windows"
    if shutil.which("pacman"):
        return "arch"
    if shutil.which("apt"):
        return "ubuntu"
    return "linux-unknown"
def get_os_label():
    if IS_WIN:
        return "Windows"
    o = detect_os()
    if o == "arch":
        return "Linux (Arch)"
    if o == "ubuntu":
        return "Linux (Ubuntu)"
    return "Linux"
def run(cmd, cwd=None, capture=True, env=None):
    try:
        p = subprocess.run(
            cmd, cwd=cwd, env=env,
            stdout=subprocess.PIPE if capture else None,
            stderr=subprocess.PIPE if capture else None,
            text=True,
            shell=isinstance(cmd, str),
        )
        return p.returncode, (p.stdout or ""), (p.stderr or "")
    except Exception as e:
        return 1, "", str(e)
def pip_install(python_exe, package, idx, total):
    pct = int(idx / total * 100)
    state["stage_pct"][stage_index["Установка зависимостей (pip)"]] = pct
    render()
    log_line(f"  Установка {package}...... {C_DIM}...{C_RESET}")
    code, out, err = run([python_exe, "-m", "pip", "install",
                          "--upgrade", "--no-input", package])
    if code == 0:
        ok_line(f"Установка {package}......")
    else:
        err_line(f"Установка {package}......")
        if err.strip():
            info_line(err.strip().splitlines()[-1])
def download(url, dest, show_name=None):
    name = show_name or os.path.basename(dest)
    log_line(f"  Загрузка {name}...... {C_DIM}...{C_RESET}")
    try:
        req = urllib.request.Request(url, headers={"User-Agent": "curl/7.68.0"})
        with urllib.request.urlopen(req, timeout=120) as r, open(dest, "wb") as f:
            total = int(r.headers.get("Content-Length", 0) or 0)
            done = 0
            chunk = 64 * 1024
            while True:
                buf = r.read(chunk)
                if not buf:
                    break
                f.write(buf)
                done += len(buf)
                if total and state["log"]:
                    pct = int(done * 100 / total)
                    state["log"][-1] = f"  Загрузка {name}...... {C_DIM}{pct}%{C_RESET}"
                    render()
        ok_line(f"Загрузка {name}......")
        return True
    except Exception as e:
        err_line(f"Загрузка {name}...... {e}")
        return False
def extract_zip(src, dest_dir):
    with zipfile.ZipFile(src, "r") as z:
        z.extractall(dest_dir)
def extract_tar_gz(src, dest_dir):
    with tarfile.open(src, "r:gz") as t:
        t.extractall(dest_dir)
def stage_create_files(app_dir):
    set_stage("Создание файлов jarvis.pyc, ui.pyc", 0)
    if not JARVIS_B64 or not UI_B64 or JARVIS_B64.startswith("@@") or UI_B64.startswith("@@"):
        stage_fail("Создание файлов jarvis.pyc, ui.pyc")
        err_line("Base64-строки не вшиты в сетапер.")
        return False
    files = [("jarvis.py", JARVIS_B64), ("ui.py", UI_B64)]
    total = len(files)
    pyc_dir = os.path.join(app_dir, "__pycache__")
    try:
        for idx, (name, b64) in enumerate(files, start=1):
            src_path = os.path.join(app_dir, name)
            pyc_path = os.path.join(app_dir, name + "c")
            with open(src_path, "wb") as f:
                f.write(base64.b64decode(b64))
            try:
                compiled = py_compile.compile(src_path, doraise=True)
            except py_compile.PyCompileError as e:
                stage_fail("Создание файлов jarvis.pyc, ui.pyc")
                err_line(f"Компиляция {name}: {e.msg}")
                return False
            shutil.move(compiled, pyc_path)
            os.remove(src_path)
            state["stage_pct"][stage_index["Создание файлов jarvis.pyc, ui.pyc"]] = int(idx / total * 100)
            render()
            info_line(f"{name} → {name}c")
        if os.path.isdir(pyc_dir) and not os.listdir(pyc_dir):
            os.rmdir(pyc_dir)
        stage_done("Создание файлов jarvis.pyc, ui.pyc")
        ok_line("Файлы скомпилированы в .pyc.")
        return True
    except Exception as e:
        stage_fail("Создание файлов jarvis.pyc, ui.pyc")
        err_line(f"{type(e).__name__}: {e}")
        return False
def venv_python(app_dir):
    if IS_WIN:
        return os.path.join(app_dir, "venv", "Scripts", "python.exe")
    return os.path.join(app_dir, "venv", "bin", "python")
def stage_create_venv(app_dir):
    set_stage("Создание виртуального окружения", 10)
    venv_dir = os.path.join(app_dir, "venv")
    code, _out, err = run([sys.executable, "-m", "venv", venv_dir])
    if code != 0:
        stage_fail("Создание виртуального окружения")
        err_line(f"venv: {err.strip()}")
        return False
    py = venv_python(app_dir)
    if not os.path.exists(py):
        stage_fail("Создание виртуального окружения")
        err_line("python в venv не найден")
        return False
    run([py, "-m", "pip", "install", "--upgrade", "pip", "--no-input"])
    stage_done("Создание виртуального окружения")
    ok_line("Виртуальное окружение создано.")
    return True
def stage_pip(app_dir):
    py = venv_python(app_dir)
    pkgs = list(PIP_PACKAGES_COMMON) + (PIP_PACKAGES_WINDOWS if IS_WIN else [])
    set_stage("Установка зависимостей (pip)", 0)
    total = len(pkgs)
    for i, pkg in enumerate(pkgs, start=1):
        pip_install(py, pkg, i, total)
    stage_done("Установка зависимостей (pip)")
    return True
def _aur_helper():
    for name in ("yay", "paru"):
        p = shutil.which(name)
        if p:
            return p
    return None
def _test_piper(piper_bin, model_path):
    test_wav = "/tmp/jarvis_piper_test.wav"
    try:
        if os.path.exists(test_wav):
            os.remove(test_wav)
        p = subprocess.run(
            [piper_bin, "--model", model_path, "--output_file", test_wav],
            input="тест".encode("utf-8"),
            stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL,
            timeout=15,
        )
        return p.returncode == 0 and os.path.exists(test_wav) and os.path.getsize(test_wav) > 0
    except Exception:
        return False
def _ensure_yay(app_dir):
    helper = _aur_helper()
    if helper:
        return helper
    info_line("AUR-хелпер (yay/paru) не найден, ставлю yay...")
    for dep in ("git", "base-devel"):
        run(["sudo", "pacman", "-S", "--needed", "--noconfirm", dep])
    if not shutil.which("git"):
        err_line("git не установлен — не могу собрать yay.")
        return None
    tmp_dir = os.path.join(app_dir, "_yay_build")
    shutil.rmtree(tmp_dir, ignore_errors=True)
    log_line(f"  git clone yay...... {C_DIM}...{C_RESET}")
    code, _o, err = run(
        ["git", "clone", "--depth", "1", "https://aur.archlinux.org/yay.git", tmp_dir]
    )
    if code != 0:
        err_line("git clone yay......")
        if err.strip():
            info_line(err.strip().splitlines()[-1])
        return None
    ok_line("git clone yay......")
    log_line(f"  makepkg -si yay...... {C_DIM}...{C_RESET}")
    code, _o, err = run(["makepkg", "-si", "--noconfirm"], cwd=tmp_dir)
    shutil.rmtree(tmp_dir, ignore_errors=True)
    helper = _aur_helper()
    if helper:
        ok_line("makepkg -si yay......")
        info_line("yay установлен.")
    else:
        err_line("makepkg -si yay......")
        if err.strip():
            info_line(err.strip().splitlines()[-1])
    return helper
def stage_system_packages(app_dir):
    set_stage("Установка системных пакетов", 0)
    os_kind = detect_os()
    if os_kind == "windows":
        info_line("Windows: системные пакеты не требуются.")
        stage_done("Установка системных пакетов")
        return True
    if os_kind == "arch":
        base_pkgs = ["wmctrl", "xdotool", "playerctl", "brightnessctl",
                     "libnotify", "espeak-ng"]
        info_line("Arch: ставлю базовые пакеты через pacman...")
        total = len(base_pkgs)
        for i, pkg in enumerate(base_pkgs, start=1):
            log_line(f"  pacman -S {pkg}...... {C_DIM}...{C_RESET}")
            code, _o, _e = run(["sudo", "pacman", "-S", "--needed", "--noconfirm", pkg])
            if code == 0:
                ok_line(f"pacman -S {pkg}......")
            else:
                err_line(f"pacman -S {pkg}......")
            state["stage_pct"][stage_index["Установка системных пакетов"]] = int(i / total * 100)
            render()
        stage_done("Установка системных пакетов")
        return True
    if os_kind == "ubuntu":
        pkgs = ["python3-venv", "libportaudio2", "playerctl",
                "brightnessctl", "wmctrl", "xdotool", "espeak-ng"]
        info_line("Ubuntu: пробую apt-get...")
        for i, pkg in enumerate(pkgs, start=1):
            log_line(f"  apt install {pkg}...... {C_DIM}...{C_RESET}")
            code, _o, _e = run(["sudo", "apt-get", "install", "-y", pkg])
            if code == 0:
                ok_line(f"apt install {pkg}......")
            else:
                err_line(f"apt install {pkg}......")
            state["stage_pct"][stage_index["Установка системных пакетов"]] = int(i / len(pkgs) * 100)
            render()
        stage_done("Установка системных пакетов")
        return True
    info_line("Неизвестный Linux: системные пакеты пропущены.")
    stage_done("Установка системных пакетов")
    return True
def stage_models(app_dir):
    set_stage("Загрузка голосовых моделей", 0)
    model_dir = os.path.join(app_dir, "model")
    if os.path.isdir(model_dir) and os.listdir(model_dir):
        info_line("Vosk-модель уже на месте.")
        state["stage_pct"][stage_index["Загрузка голосовых моделей"]] = 40
        render()
    else:
        tmp_zip = os.path.join(app_dir, "_vosk.zip")
        if not download(VOSK_URL, tmp_zip, "vosk-model-small-ru-0.22.zip"):
            stage_fail("Загрузка голосовых моделей")
            return False
        state["stage_pct"][stage_index["Загрузка голосовых моделей"]] = 30
        render()
        try:
            extract_zip(tmp_zip, app_dir)
            extracted = os.path.join(app_dir, VOSK_ZIP_INNER)
            if os.path.isdir(extracted):
                if os.path.isdir(model_dir):
                    shutil.rmtree(model_dir)
                os.rename(extracted, model_dir)
            os.remove(tmp_zip)
        except Exception as e:
            stage_fail("Загрузка голосовых моделей")
            err_line(f"Распаковка vosk: {e}")
            return False
        state["stage_pct"][stage_index["Загрузка голосовых моделей"]] = 40
        render()
    onnx_path = os.path.join(app_dir, PIPER_VOICE_ONNX_NAME)
    json_path = os.path.join(app_dir, PIPER_VOICE_JSON_NAME)
    ok = True
    if not os.path.exists(onnx_path):
        ok = download(PIPER_VOICE_ONNX, onnx_path, PIPER_VOICE_ONNX_NAME) and ok
    else:
        info_line("Голос Piper (.onnx) уже на месте.")
    state["stage_pct"][stage_index["Загрузка голосовых моделей"]] = 70
    render()
    if not os.path.exists(json_path):
        ok = download(PIPER_VOICE_JSON, json_path, PIPER_VOICE_JSON_NAME) and ok
    else:
        info_line("Голос Piper (.json) уже на месте.")
    
    if ok and os.path.exists(json_path):
        try:
            with open(json_path, "r", encoding="utf-8") as f:
                data = json.load(f)
            if "phoneme_id_map" in data:
                bad_keys = [k for k in data["phoneme_id_map"] if len(k) > 1]
                if bad_keys:
                    for k in bad_keys:
                        del data["phoneme_id_map"][k]
                    with open(json_path, "w", encoding="utf-8") as f:
                        json.dump(data, f, ensure_ascii=False, indent=2)
                    info_line(f"Удалены несовместимые фонемы ({len(bad_keys)} шт.).")
        except Exception as e:
            err_line(f"Ошибка при очистке .json: {e}")
            
    if not ok:
        stage_fail("Загрузка голосовых моделей")
        return False
    stage_done("Загрузка голосовых моделей")
    return True
def _install_piper_local(app_dir):
    piper_dir = os.path.join(app_dir, "piper")
    if os.path.isdir(piper_dir) and os.listdir(piper_dir):
        info_line("Piper уже установлен локально.")
        return True
    tmp_archive = os.path.join(app_dir, "_piper.tar.gz")
    if not download(PIPER_LINUX_URL, tmp_archive, "piper_linux_x86_64.tar.gz"):
        return False
    state["stage_pct"][stage_index["Установка Piper"]] = 50
    render()
    try:
        os.makedirs(piper_dir, exist_ok=True)
        extract_tar_gz(tmp_archive, piper_dir)
        os.remove(tmp_archive)
        found = False
        for root, _dirs, files in os.walk(piper_dir):
            if "piper" in files:
                bin_path = os.path.join(root, "piper")
                if os.path.isfile(bin_path):
                    os.chmod(bin_path, 0o755)
                    found = True
        if not found:
            info_line("Бинарник piper не найден после распаковки.")
        ok_line("Piper скачан и распакован.")
        return True
    except Exception as e:
        err_line(f"Распаковка Piper: {e}")
        return False
def stage_piper(app_dir):
    set_stage("Установка Piper", 0)
    if IS_WIN:
        piper_dir = os.path.join(app_dir, "piper")
        if os.path.isdir(piper_dir) and os.listdir(piper_dir):
            info_line("Piper уже установлен.")
            stage_done("Установка Piper")
            return True
        tmp_zip = os.path.join(app_dir, "_piper.zip")
        if not download(PIPER_WIN_URL, tmp_zip, "piper_windows_amd64.zip"):
            stage_fail("Установка Piper")
            return False
        state["stage_pct"][stage_index["Установка Piper"]] = 70
        render()
        try:
            extract_zip(tmp_zip, app_dir)
            if not (os.path.isdir(piper_dir) and os.listdir(piper_dir)):
                for root, _d, files in os.walk(app_dir):
                    if "piper.exe" in files:
                        os.makedirs(piper_dir, exist_ok=True)
                        for f in os.listdir(root):
                            src = os.path.join(root, f)
                            if os.path.isfile(src):
                                shutil.move(src, os.path.join(piper_dir, f))
                        break
            os.remove(tmp_zip)
        except Exception as e:
            stage_fail("Установка Piper")
            err_line(f"Распаковка piper: {e}")
            return False
        stage_done("Установка Piper")
        ok_line("Piper установлен.")
        return True
    if not _install_piper_local(app_dir):
        stage_fail("Установка Piper")
        return False
    piper_bin = None
    for root, _dirs, files in os.walk(os.path.join(app_dir, "piper")):
        if "piper" in files and os.access(os.path.join(root, "piper"), os.X_OK):
            piper_bin = os.path.join(root, "piper")
            break
    model_path = os.path.join(app_dir, PIPER_VOICE_ONNX_NAME)
    if piper_bin and os.path.exists(model_path):
        if _test_piper(piper_bin, model_path):
            info_line("Проверка Piper + русская модель: [ОК]")
        else:
            info_line("Проверка Piper + русская модель: [ОШИБКА]")
    stage_done("Установка Piper")
    return True
def cleanup_on_exit():
    sys.stdout.write(SHOW_CURSOR)
    sys.stdout.flush()
def main():
    if sys.version_info < (3, 9):
        print("Требуется Python 3.9+")
        return 1
    base_dir = os.path.dirname(os.path.abspath(__file__))
    app_dir = os.path.join(base_dir, APP_DIR_NAME)
    if os.path.exists(app_dir):
        try:
            shutil.rmtree(app_dir)
        except Exception:
            pass
    os.makedirs(app_dir, exist_ok=True)
    render()
    info_line(f"Папка установки: {app_dir}")
    info_line(f"Платформа: {get_os_label()}")
    steps = [
        ("Создание файлов jarvis.pyc, ui.pyc", lambda: stage_create_files(app_dir)),
        ("Создание виртуального окружения",    lambda: stage_create_venv(app_dir)),
        ("Установка зависимостей (pip)",       lambda: stage_pip(app_dir)),
        ("Установка системных пакетов",        lambda: stage_system_packages(app_dir)),
        ("Загрузка голосовых моделей",         lambda: stage_models(app_dir)),
        ("Установка Piper",                    lambda: stage_piper(app_dir)),
    ]
    for name, fn in steps:
        try:
            ok = fn()
        except Exception as e:
            stage_fail(name)
            err_line(f"{type(e).__name__}: {e}")
            ok = False
        if not ok:
            log_line(f"{C_RED}Установка прервана на этапе: {name}{C_RESET}")
            cleanup_on_exit()
            return 1

    # ================= ВОЗВРАТ ПРАВ (только Linux) =================
    if not IS_WIN:
        real_user = os.environ.get("SUDO_USER")
        if not real_user:
            if os.geteuid() == 0:
                users = [d for d in os.listdir("/home") if os.path.isdir(os.path.join("/home", d))]
                real_user = users[0] if len(users) == 1 else "user"
            else:
                real_user = os.environ.get("USER")
        if real_user and real_user != "root":
            try:
                shutil.chown(app_dir, user=real_user)
                for rd, dirs, files in os.walk(app_dir):
                    for d in dirs:
                        shutil.chown(os.path.join(rd, d), user=real_user)
                    for f in files:
                        shutil.chown(os.path.join(rd, f), user=real_user)
                info_line(f"Владение {app_dir} возвращено пользователю {real_user}.")
            except Exception as e:
                err_line(f"Не удалось вернуть владение: {e}")
                info_line(f"Вручную: chown -R {real_user}:{real_user} {app_dir}")

    render()
    print(f"{C_GREEN}{C_BOLD}Готово!{C_RESET}\n")

    # ================= КОМАНДА ЗАПУСКА =================
    if IS_WIN:
        run_cmd = f'"{os.path.join(app_dir, "venv", "Scripts", "python.exe")}" "{os.path.join(app_dir, "jarvis.pyc")}"'
    else:
        run_cmd = f'"{os.path.join(app_dir, "venv", "bin", "python")}" "{os.path.join(app_dir, "jarvis.pyc")}"'

    # ================= ЯРЛЫК =================
    def create_shortcut():
        try:
            if IS_WIN:
                desktop = os.path.join(os.path.expanduser("~"), "Desktop")
                lnk = os.path.join(desktop, "J.A.R.V.I.S..lnk")
                pyw = os.path.join(app_dir, "venv", "Scripts", "pythonw.exe")
                script = os.path.join(app_dir, "jarvis.pyc")
                ps = (
                    "$ws = New-Object -ComObject WScript.Shell; "
                    f"$s = $ws.CreateShortcut('{lnk}'); "
                    f"$s.TargetPath = '{pyw}'; "
                    f"$s.Arguments = '\"{script}\"'; "
                    f"$s.WorkingDirectory = '{app_dir}'; "
                    "$s.Save()"
                )
                subprocess.run(["powershell", "-NoProfile", "-Command", ps],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL, timeout=20)
                return os.path.exists(lnk), lnk
            else:
                desktop = None
                for name in ("Desktop", "Рабочий стол", "Рабочий_стол"):
                    p = os.path.join(os.path.expanduser("~"), name)
                    if os.path.isdir(p):
                        desktop = p
                        break
                if not desktop:
                    desktop = os.path.join(os.path.expanduser("~"), "Desktop")
                desktop_lnk = os.path.join(desktop, "J.A.R.V.I.S..desktop")
                content = (
                    "[Desktop Entry]\n"
                    "Type=Application\n"
                    "Name=J.A.R.V.I.S.\n"
                    f"Exec={run_cmd}\n"
                    f"Path={app_dir}\n"
                    "Terminal=true\n"
                    "Icon=utilities-terminal\n"
                    "Categories=Utility;\n"
                )
                os.makedirs(desktop, exist_ok=True)
                with open(desktop_lnk, "w", encoding="utf-8") as f:
                    f.write(content)
                os.chmod(desktop_lnk, 0o755)
                apps_dir = os.path.join(os.path.expanduser("~"), ".local", "share", "applications")
                os.makedirs(apps_dir, exist_ok=True)
                menu_lnk = os.path.join(apps_dir, "jarvis.desktop")
                with open(menu_lnk, "w", encoding="utf-8") as f:
                    f.write(content)
                os.chmod(menu_lnk, 0o755)
                subprocess.run(["update-desktop-database", apps_dir],
                               stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
                return os.path.exists(desktop_lnk), desktop_lnk
        except Exception as e:
            err_line(f"Ошибка создания ярлыка: {e}")
            return False, None

    # ================= СПРАШИВАЕМ И ВЫХОДИМ =================
    if sys.stdin.isatty():
        sys.stdout.write(SHOW_CURSOR)
        sys.stdout.write(f"{C_CYAN}Создать ярлык на рабочем столе? [y/N]: {C_RESET}")
        sys.stdout.flush()
        try:
            answer = input().strip().lower()
        except EOFError:
            answer = ""
        if answer in ("y", "yes", "д", "да"):
            ok, path = create_shortcut()
            if ok:
                print(f"{C_GREEN}Ярлык создан:{C_RESET} {path}")
                print("Готово. Установщик завершён.")
            else:
                print(f"{C_RED}Не удалось создать ярлык.{C_RESET}")
                print(f"Запуск вручную:\n  {run_cmd}")
        else:
            print(f"Запуск Джарвиса:\n  {run_cmd}")
    else:
        print(f"Запуск Джарвиса:\n  {run_cmd}")

    print("\nНе забудьте настроить API-ключ в настройках (кнопка «Настройки» в UI).")
    cleanup_on_exit()
    return 0
if __name__ == "__main__":
    try:
        sys.exit(main())
    except KeyboardInterrupt:
        cleanup_on_exit()
        print("\nПрервано пользователем.")
        sys.exit(130)
